// ==UserScript==
// @name         链接打开方式控制器
// @icon         data:image/png;base64,
// @namespace    gaio-x
// @version      1.0.1
// @description  可自由拖动（支持触屏）的全局悬浮按钮：点击切换信息气泡(popover)显隐，气泡在靠近按钮的方位自动选位平滑展开并稳定常显；使用 GM_openInTab 可靠控制前后台打开，选项持久化；浏览器全屏与视频网页全屏（如B站网页全屏）均自动隐藏
// @author       gaio-x
// @match        *://*/*
// @match        file:///*
// @grant        GM_getValue
// @grant        GM_setValue
// @grant        GM_openInTab
// @grant        GM_addValueChangeListener
// @run-at       document-idle
// ==/UserScript==

(function () {
    'use strict';

    // 存储键
    var KEY_MODE = 'loc_mode';       // 模式：0=无 1=新窗并切换 2=新窗不切换
    var KEY_POS = 'loc_pos';         // 悬浮按钮位置 {x, y}
    var KEY_OPEN = 'loc_open';       // 气泡常显：0=否 1=是
    var KEY_ICON = 'loc_icon';       // 图标皮肤索引
    var KEY_OPACITY = 'loc_opacity'; // 面板背景不透明度 0.2~1
    var KEY_FABSIZE = 'loc_size';    // 悬浮按钮尺寸 40~120
    var PANEL_ID = 'loc-panel';
    var FAB_ID = 'loc-fab';
    var STYLE_ID = 'loc-style';

    var PANEL_W = 146;  // 气泡宽度
    var GAP = 8;        // 气泡与按钮间距
    var DRAG_THRESHOLD = 4; // 点击/拖拽判定阈值
    var FAB_SIZE = 80, FAB_MIN = 40, FAB_MAX = 120; // 当前尺寸与可调范围

    // 悬浮按钮图标皮肤：全部 PNG 均以 base64 内嵌（脚本运行于任意网页，
    // 无法引用本地 file:// 路径；内嵌可保证跨浏览器、跨机器可用）
    var ICON_SKINS = [
        'data:image/png;base64,',
        'data:image/png;base64,',
        'data:image/png;base64,',
        'data:image/png;base64,',
        'data:image/png;base64,',
        'data:image/png;base64,',
        'data:image/png;base64,',
        'data:image/png;base64,',
        'data:image/png;base64,',
        'data:image/png;base64,',
        'data:image/png;base64,'
    ];
    // 各皮肤名称（用于缩略图悬停提示），与 ICON_SKINS 一一对应
    var ICON_NAMES = ["独角兽","独角兽2","独角兽3","安克雷奇","贝劳森林","柴郡","马克斯·殷麦曼","四万十","瓦尔帕莱索","雅努斯","时崎狂三"];

    var currentMode = 0;
    var panel = null;
    var fab = null;

    // 面板分区：按气泡方位调整排列顺序
    var titleEl = null;
    var btnsEl = null;
    var skinsEl = null;

    var popoverOpen = false;   // 气泡显隐，仅由 FAB 点击切换（持久化）
    var lastNormalPos = null;  // 进入全屏前位置快照
    var wasFullscreen = false; // 上一次同步时的浏览器全屏状态
    var webFullscreen = false; // 视频网页全屏（不触发 Fullscreen API，需单独检测）

    // 存储封装：优先 GM API，回退 localStorage
    var storage = {
        get: function (key, def) {
            try {
                if (typeof GM_getValue === 'function') return GM_getValue(key, def);
            } catch (e) {}
            try {
                var v = window.localStorage.getItem(key);
                return v === null ? def : v;
            } catch (e) {
                return def;
            }
        },
        set: function (key, val) {
            try {
                if (typeof GM_setValue === 'function') { GM_setValue(key, val); return; }
            } catch (e) {}
            try {
                window.localStorage.setItem(key, val);
            } catch (e) {}
        }
    };

    // 模式值归一化：兼容数字/字符串，仅返回 0/1/2
    function normalizeMode(v) {
        v = parseInt(v, 10);
        return (v === 1 || v === 2) ? v : 0;
    }

    function loadMode() {
        return normalizeMode(storage.get(KEY_MODE, 0));
    }

    // 跨帧/跨标签监听模式变更，使点击路径免读存储
    function enableModeSync() {
        if (typeof GM_addValueChangeListener !== 'function') return false;
        try {
            GM_addValueChangeListener(KEY_MODE, function (name, oldV, newV) {
                currentMode = normalizeMode(newV);
                refreshActiveButtons();
            });
            return true;
        } catch (e) {
            return false;
        }
    }

    var modeSyncActive = false; // 是否已启用跨帧监听

    currentMode = loadMode();

    var currentIcon = parseInt(storage.get(KEY_ICON, 0), 10);
    if (!(currentIcon >= 0 && currentIcon < ICON_SKINS.length)) currentIcon = 0;

    // 气泡显隐；旧版本键 loc_pinned 惰性回读
    var openRaw = storage.get(KEY_OPEN, null);
    if (openRaw === null) openRaw = storage.get('loc_pinned', 0);
    popoverOpen = parseInt(openRaw, 10) === 1;

    var bgAlpha = parseFloat(storage.get(KEY_OPACITY, 1));
    if (!(bgAlpha >= 0.2 && bgAlpha <= 1)) bgAlpha = 1;

    var savedFabSize = parseInt(storage.get(KEY_FABSIZE, FAB_SIZE), 10);
    if (!(savedFabSize >= FAB_MIN && savedFabSize <= FAB_MAX)) savedFabSize = FAB_SIZE;

    /* 链接拦截：document 捕获阶段单监听器，SPA 动态加载的链接同样生效 */
    var SPECIAL_PROTOCOL_RE =
        /^(javascript|mailto|tel|sms|data|about|blob|view-source|chrome|chrome-extension|moz-extension|ms-browser-extension|file):/i;

    // 从事件路径找 <a>；无 composedPath 时回退 closest
    function findAnchor(path, target) {
        if (path) {
            for (var i = 0; i < path.length; i++) {
                var n = path[i];
                if (n.nodeType === 1 && n.tagName && n.tagName.toLowerCase() === 'a') return n;
            }
            return null;
        }
        return target && target.closest ? target.closest('a') : null;
    }

    // 真实地址：兼容 SVG <a> 的 href.baseVal
    function getAnchorUrl(a) {
        var raw = a.getAttribute('href');
        if (raw === null || raw === '') return '';
        if (typeof a.href === 'string') return a.href;
        if (a.href && typeof a.href.baseVal === 'string') return a.href.baseVal;
        return raw;
    }

    function shouldSkip(a, url) {
        var rawAttr = a.getAttribute('href');
        if (rawAttr === null) return true;
        // 空 href / 页内锚点不拦截
        if (rawAttr === '' || rawAttr.replace(/\s/g, '') === '' || rawAttr.charAt(0) === '#') return true;
        if (SPECIAL_PROTOCOL_RE.test(url)) return true;
        if (a.hasAttribute && a.hasAttribute('download')) return true;
        return false;
    }

    function handleLinkClick(e) {
        try {
            if (e.button !== 0) return;                            // 仅左键
            if (e.ctrlKey || e.metaKey || e.shiftKey || e.altKey) return; // 修饰键尊重默认
            if (e.defaultPrevented) return;                       // 站点已自行处理

            var path = typeof e.composedPath === 'function' ? e.composedPath() : null;
            var a = findAnchor(path, e.target);
            if (!a) return;
            if (a.hasAttribute && a.hasAttribute('data-loc-self')) return; // 脚本合成的锚点
            if (a.closest && a.closest('#' + PANEL_ID + ',#' + FAB_ID)) return;

            var url = getAnchorUrl(a);
            if (!url || shouldSkip(a, url)) return;

            var mode = modeSyncActive ? currentMode : loadMode();
            if (mode === 0) return;

            e.preventDefault();
            e.stopPropagation();
            openLink(url, mode === 1);
        } catch (err) {
            try { console.warn('[链接打开方式控制器] 点击处理异常:', err); } catch (x) {}
        }
    }

    /* 新标签打开统一入口：active 控制是否切换到新标签 */
    function openLink(url, active) {
        // 首选 GM_openInTab：前后台语义由扩展保证
        if (typeof GM_openInTab === 'function') {
            try {
                GM_openInTab(url, {
                    active: active,
                    setParent: true,
                    noopener: true,
                    insert: true
                });
                return;
            } catch (e) {}
        }

        if (active) {
            // 不能带 noopener 特性串：window.open 会返回 null 被误判拦截（曾导致重复开两个标签）
            var w = null;
            try {
                w = window.open(url, '_blank');
            } catch (e) {}
            if (w) {
                try { w.opener = null; } catch (e) {}
            } else {
                dispatchAnchor(url, false);
            }
        } else {
            dispatchAnchor(url, true);
        }
    }

    // 合成锚点兜底：挂入文档、data-loc-self 防拦截器递归；background 带修饰键模拟 Ctrl+点击
    function dispatchAnchor(url, background) {
        var a = document.createElement('a');
        a.href = url;
        a.target = '_blank';
        a.rel = 'noopener noreferrer';
        a.setAttribute('data-loc-self', '1');
        document.body.appendChild(a);

        var ev;
        try {
            ev = new MouseEvent('click', {
                view: window,
                bubbles: true,
                cancelable: true,
                ctrlKey: !!background,
                metaKey: !!background
            });
        } catch (e) {
            // 极旧内核兜底
            ev = document.createEvent('MouseEvents');
            ev.initMouseEvent('click', true, true, window, 0,
                0, 0, 0, 0, !!background, false, false, false, 0, null);
        }

        a.dispatchEvent(ev);
        if (a.parentNode) a.parentNode.removeChild(a);
    }

    function injectStyles() {
        if (document.getElementById(STYLE_ID)) return;
        var css = '' +
            '#' + PANEL_ID + '{' +
            'position:fixed;' +
            'width:' + PANEL_W + 'px;' +
            'left:0;top:0;' +
            'font-family:-apple-system,BlinkMacSystemFont,"Segoe UI","PingFang SC","Microsoft YaHei",sans-serif;' +
            'color:#333;' +
            'background:rgba(255,255,255,var(--loc-alpha,1));' +
            'border:1px solid rgba(0,0,0,.09);' +
            'border-radius:10px;' +
            'box-shadow:0 8px 28px rgba(0,0,0,.20),0 1px 4px rgba(0,0,0,.10);' +
            'overflow:hidden;' +
            '-webkit-user-select:none;user-select:none;' +
            'box-sizing:border-box;' +
            'transform-origin:bottom right;' +
            'opacity:0;' +
            'transform:scale(.9);' +
            'visibility:hidden;' +
            'pointer-events:none;' +
            'transition:opacity .18s ease,' +
            'transform .2s cubic-bezier(.2,.9,.3,1.2),' +
            'visibility 0s linear .2s;' +
            '}' +
            '#' + PANEL_ID + '.loc-open{' +
            'opacity:1;' +
            'transform:scale(1);' +
            'visibility:visible;' +
            'pointer-events:auto;' +
            'transition:opacity .18s ease,' +
            'transform .22s cubic-bezier(.2,.9,.3,1.2),' +
            'visibility 0s;' +
            '}' +
            '#' + PANEL_ID + ' .loc-title{' +
            'padding:5px 10px;' +
            'font-size:11px;font-weight:normal;color:#80868b;' +
            'background:linear-gradient(' +
            'rgba(255,255,255,var(--loc-alpha,1)),' +
            'rgba(241,243,245,var(--loc-alpha,1)));' +
            'border-bottom:1px solid rgba(0,0,0,.06);' +
            '}' +
            '#' + PANEL_ID + ' .loc-btns{display:flex;flex-direction:row;gap:6px;padding:7px;}' +
            '#' + PANEL_ID + ' .loc-btns button{' +
            'flex:1 1 0;min-width:0;' +
            'height:40px;' +
            'margin:0;padding:0;' +
            'box-sizing:border-box;' +
            'display:flex;align-items:center;justify-content:center;' +
            'font:inherit;font-size:11px;line-height:1.25;' +
            'white-space:pre-line;' +
            'color:#80868b;text-align:center;' +
            'background:rgba(255,255,255,var(--loc-alpha,1));border:1px solid #dadce0;border-radius:6px;' +
            'cursor:pointer;-webkit-appearance:none;appearance:none;' +
            'transition:background-color .12s ease,border-color .12s ease,color .12s ease,transform .08s ease,box-shadow .12s ease;' +
            '}' +
            '#' + PANEL_ID + ' .loc-btns button:hover{' +
            'border-color:#5a95ff;color:#2563eb;background:#f4f8ff;' +
            '}' +
            '#' + PANEL_ID + ' .loc-btns button:active{transform:scale(.95);}' +
            '#' + PANEL_ID + ' .loc-btns button.loc-active,' +
            '#' + PANEL_ID + ' .loc-btns button.loc-active:hover{' +
            'color:#fff;' +
            'background:linear-gradient(#5b96ff,#3b7bf0);' +
            'border-color:#3b7bf0;' +
            'box-shadow:0 1px 3px rgba(59,123,240,.45);' +
            '}' +
            '#' + FAB_ID + '{' +
            'position:fixed;right:16px;bottom:16px;' +
            'width:' + FAB_SIZE + 'px;height:' + FAB_SIZE + 'px;padding:0;margin:0;' +
            'display:flex;align-items:center;justify-content:center;' +
            'background:transparent;' +
            'border:none;' +
            'cursor:grab;' +
            'touch-action:none;' +
            '-webkit-appearance:none;appearance:none;' +
            'transition:transform .15s ease;' +
            '}' +
            '#' + FAB_ID + ' img{' +
            'width:100%;height:100%;display:block;' +
            'object-fit:contain;' +
            'filter:drop-shadow(0 3px 5px rgba(0,0,0,.35));' +
            '-webkit-user-drag:none;' +
            'user-select:none;-webkit-user-select:none;' +
            'pointer-events:none;' +
            'transition:filter .15s ease;' +
            '}' +
            '#' + FAB_ID + ':hover{' +
            'transform:scale(1.1);' +
            '}' +
            '#' + FAB_ID + ':hover img{' +
            'filter:drop-shadow(0 6px 9px rgba(0,0,0,.4));' +
            '}' +
            '#' + FAB_ID + ':active{transform:scale(.9);}' +
            '#' + FAB_ID + '.loc-grabbing,' +
            '#' + FAB_ID + '.loc-grabbing:hover,' +
            '#' + FAB_ID + '.loc-grabbing:active{' +
            'cursor:grabbing;' +
            'transform:none;' +
            'transition:none;' +
            '}' +
            '#' + FAB_ID + '.loc-grabbing img,' +
            '#' + FAB_ID + '.loc-grabbing:hover img{transition:none;}' +
            '#' + FAB_ID + '.loc-on img{' +
            'filter:drop-shadow(0 0 5px rgba(91,150,255,.95))' +
            'drop-shadow(0 0 2px rgba(59,123,240,.9))' +
            'drop-shadow(0 3px 5px rgba(0,0,0,.35));' +
            '}' +
            '#' + PANEL_ID + ' .loc-skins{' +
            'border-top:1px solid rgba(0,0,0,.08);padding:5px 7px 7px;' +
            '}' +
            '#' + PANEL_ID + ' .loc-skins-label{' +
            'font-size:11px;color:#80868b;padding:0 2px 4px;' +
            '}' +
            '#' + PANEL_ID + ' .loc-skins-row{' +
            'display:flex;flex-wrap:wrap;gap:6px;justify-content:center;' +
            'max-height:164px;overflow-y:auto;' +
            '}' +
            '#' + PANEL_ID + ' .loc-skin{' +
            'width:36px;height:36px;padding:2px;margin:0;' +
            'border:1px solid #dadce0;border-radius:8px;' +
            'background:rgba(255,255,255,var(--loc-alpha,1));' +
            'cursor:pointer;-webkit-appearance:none;appearance:none;' +
            'display:flex;align-items:center;justify-content:center;' +
            'transition:border-color .12s ease,box-shadow .12s ease,transform .08s ease;' +
            '}' +
            '#' + PANEL_ID + ' .loc-skin img{' +
            'width:100%;height:100%;display:block;object-fit:contain;' +
            'pointer-events:none;-webkit-user-drag:none;' +
            '}' +
            '#' + PANEL_ID + ' .loc-skin:hover{border-color:#5a95ff;}' +
            '#' + PANEL_ID + ' .loc-skin:active{transform:scale(.92);}' +
            '#' + PANEL_ID + ' .loc-skin.loc-skin-on{' +
            'border-color:#3b7bf0;box-shadow:0 0 0 2px rgba(59,123,240,.3);' +
            '}' +
            '#' + PANEL_ID + ' .loc-opacity{' +
            'display:flex;align-items:center;gap:6px;padding-top:7px;' +
            '}' +
            '#' + PANEL_ID + ' .loc-opacity-label{' +
            'display:flex;align-items:center;justify-content:flex-start;gap:3px;' +
            'width:52px;flex-shrink:0;' +
            'font-size:11px;color:#80868b;white-space:nowrap;' +
            '}' +
            '#' + PANEL_ID + ' .loc-opacity-range{' +
            'flex:1;min-width:0;margin:0;height:14px;cursor:pointer;' +
            'accent-color:#3b7bf0;' +
            '}' +
            '#' + PANEL_ID + ' .loc-size-value{color:#80868b;}' +
            '#' + PANEL_ID + '.loc-skins-top .loc-skins{' +
            'border-top:none;border-bottom:1px solid rgba(0,0,0,.08);' +
            'padding:7px;' +
            '}' +
            '#' + PANEL_ID + '.loc-translucent{' +
            '-webkit-backdrop-filter:blur(6px);backdrop-filter:blur(6px);' +
            '}' +
            '#' + PANEL_ID + '.loc-fs-hidden,' +
            '#' + FAB_ID + '.loc-fs-hidden{display:none !important;}';
        var style = document.createElement('style');
        style.id = STYLE_ID;
        style.textContent = css;
        document.head.appendChild(style);
    }

    function buildPanel() {
        panel = document.createElement('div');
        panel.id = PANEL_ID;
        panel.style.zIndex = '2147483647';

        var title = document.createElement('div');
        title.className = 'loc-title';
        title.textContent = '链接打开方式';
        titleEl = title;

        var btnsWrap = document.createElement('div');
        btnsWrap.className = 'loc-btns';
        btnsEl = btnsWrap;
        var options = [
            { mode: 0, label: '无', desc: '不干预，保持浏览器默认行为' },
            { mode: 1, label: '新窗\n并切换', desc: '打开新窗并切换到该窗口' },
            { mode: 2, label: '新窗\n不切换', desc: '后台打开新窗，不切换窗口' }
        ];
        for (var i = 0; i < options.length; i++) {
            (function (opt) {
                var btn = document.createElement('button');
                btn.type = 'button';
                btn.setAttribute('data-mode', String(opt.mode));
                btn.textContent = opt.label;
                btn.title = opt.desc;
                btn.addEventListener('click', function () {
                    currentMode = opt.mode;
                    storage.set(KEY_MODE, opt.mode);
                    refreshActiveButtons();
                });
                btnsWrap.appendChild(btn);
            })(options[i]);
        }

        panel.appendChild(title);
        panel.appendChild(btnsWrap);

        var skinsWrap = document.createElement('div');
        skinsWrap.className = 'loc-skins';
        skinsEl = skinsWrap;
        var skinsLabel = document.createElement('div');
        skinsLabel.className = 'loc-skins-label';
        skinsLabel.textContent = '图标';
        var skinsRow = document.createElement('div');
        skinsRow.className = 'loc-skins-row';
        for (var si = 0; si < ICON_SKINS.length; si++) {
            (function (idx) {
                var skinBtn = document.createElement('button');
                skinBtn.type = 'button';
                skinBtn.className = 'loc-skin';
                skinBtn.setAttribute('data-icon', String(idx));
                skinBtn.title = ICON_NAMES[idx] || ('图标 ' + (idx + 1));
                var skinImg = document.createElement('img');
                skinImg.src = ICON_SKINS[idx];
                skinImg.alt = '';
                skinImg.draggable = false;
                skinBtn.appendChild(skinImg);
                skinBtn.addEventListener('click', function () {
                    currentIcon = idx;
                    storage.set(KEY_ICON, idx);
                    var fabImg = fab.querySelector('img'); // 仅换图，位置与交互状态全部保留
                    if (fabImg) fabImg.src = ICON_SKINS[idx];
                    refreshActiveSkins();
                });
                skinsRow.appendChild(skinBtn);
            })(si);
        }
        skinsWrap.appendChild(skinsLabel);
        skinsWrap.appendChild(skinsRow);

        // 背景透明滑条
        var opWrap = document.createElement('div');
        opWrap.className = 'loc-opacity';
        var opLabel = document.createElement('span');
        opLabel.className = 'loc-opacity-label';
        opLabel.textContent = '背景透明';
        var opRange = document.createElement('input');
        opRange.type = 'range';
        opRange.className = 'loc-opacity-range';
        opRange.min = '0.2';
        opRange.max = '1';
        opRange.step = '0.05';
        opRange.value = String(bgAlpha);
        opRange.title = '调整气泡面板背景不透明度';
        opRange.addEventListener('input', function () {
            applyAlpha(parseFloat(opRange.value));
        });
        opRange.addEventListener('change', function () {
            storage.set(KEY_OPACITY, parseFloat(opRange.value));
        });
        opWrap.appendChild(opLabel);
        opWrap.appendChild(opRange);
        skinsWrap.appendChild(opWrap);

        // 尺寸滑条：拖动中气泡锁定不动，松手后重定位一次
        var sizeWrap = document.createElement('div');
        sizeWrap.className = 'loc-opacity';
        var sizeLabel = document.createElement('span');
        sizeLabel.className = 'loc-opacity-label';
        var sizeLabelText = document.createElement('span');
        sizeLabelText.textContent = '尺寸';
        var sizeValue = document.createElement('span');
        sizeValue.className = 'loc-size-value';
        sizeValue.textContent = FAB_SIZE;
        sizeLabel.appendChild(sizeLabelText);
        sizeLabel.appendChild(sizeValue);
        var sizeRange = document.createElement('input');
        sizeRange.type = 'range';
        sizeRange.className = 'loc-opacity-range loc-size-range';
        sizeRange.min = String(FAB_MIN);
        sizeRange.max = String(FAB_MAX);
        sizeRange.step = '2';
        sizeRange.value = String(FAB_SIZE);
        sizeRange.title = '调整悬浮按钮显示尺寸';
        sizeRange.addEventListener('input', function () {
            applyFabSize(parseInt(sizeRange.value, 10), false, true);
        });
        sizeRange.addEventListener('change', function () {
            var s = parseInt(sizeRange.value, 10);
            storage.set(KEY_FABSIZE, s);
            applyFabSize(s, false, false);
        });
        sizeWrap.appendChild(sizeLabel);
        sizeWrap.appendChild(sizeRange);
        skinsWrap.appendChild(sizeWrap);

        panel.appendChild(skinsWrap);
        document.body.appendChild(panel);

        refreshActiveButtons();
        refreshActiveSkins();
        applyAlpha(bgAlpha);
    }

    function applyAlpha(a) {
        if (!(a >= 0.2 && a <= 1)) a = 1;
        bgAlpha = a;
        if (panel) {
            panel.style.setProperty('--loc-alpha', String(a));
            panel.classList.toggle('loc-translucent', a < 0.999);
        }
    }

    // 调整 FAB 尺寸：宽高更新后以左上角为锚裁剪入视口；keepStable 时气泡保持原位
    function applyFabSize(size, persist, keepStable) {
        size = parseInt(size, 10);
        if (!(size >= FAB_MIN && size <= FAB_MAX)) size = FAB_SIZE;
        FAB_SIZE = size;

        if (fab) {
            fab.style.width = size + 'px';
            fab.style.height = size + 'px';
            var pos = readFabPos(); // 隐藏期间返回 null，退出全屏后恢复
            if (pos) {
                var c = clampFabPosition(pos.x, pos.y);
                fab.style.left = c.x + 'px';
                fab.style.top = c.y + 'px';
                if (!keepStable && popoverOpen && !isFullscreenNow() && !webFullscreen) {
                    positionPopover();
                }
            }
        }

        if (panel) {
            var sr = panel.querySelector('.loc-size-range');
            if (sr) sr.value = String(size);
            var sv = panel.querySelector('.loc-size-value');
            if (sv) sv.textContent = size;
        }

        if (persist) storage.set(KEY_FABSIZE, size);
    }

    /* 分区重排：模式按钮区始终贴靠 FAB 一侧，皮肤区在远端（仅顺序变化时移动节点） */
    var modeFirstLast = null;
    function arrangeSections(modeFirst) {
        if (modeFirstLast === modeFirst) return;
        modeFirstLast = modeFirst;
        if (modeFirst) {
            panel.appendChild(titleEl);
            panel.appendChild(btnsEl);
            panel.appendChild(skinsEl);
        } else {
            panel.appendChild(skinsEl);
            panel.appendChild(titleEl);
            panel.appendChild(btnsEl);
        }
        panel.classList.toggle('loc-skins-top', !modeFirst);
    }

    function refreshActiveSkins() {
        if (!panel) return;
        var sbtns = panel.querySelectorAll('button[data-icon]');
        for (var i = 0; i < sbtns.length; i++) {
            var active = parseInt(sbtns[i].getAttribute('data-icon'), 10) === currentIcon;
            sbtns[i].classList.toggle('loc-skin-on', active);
            sbtns[i].setAttribute('aria-pressed', active ? 'true' : 'false');
        }
    }

    function refreshActiveButtons() {
        if (!panel) return;
        var btns = panel.querySelectorAll('button[data-mode]');
        for (var i = 0; i < btns.length; i++) {
            var active = parseInt(btns[i].getAttribute('data-mode'), 10) === currentMode;
            btns[i].classList.toggle('loc-active', active);
            btns[i].setAttribute('aria-pressed', active ? 'true' : 'false');
        }
    }

    function buildFab() {
        fab = document.createElement('button');
        fab.type = 'button';
        fab.id = FAB_ID;
        fab.style.zIndex = '2147483646';
        fab.setAttribute('aria-controls', PANEL_ID);

        var icon = document.createElement('img');
        icon.src = ICON_SKINS[currentIcon];
        icon.alt = '';
        icon.setAttribute('aria-hidden', 'true');
        icon.draggable = false;
        fab.appendChild(icon);

        // 点击切换气泡；拖拽后的 click 由 suppressClick 抑制
        fab.addEventListener('click', function (e) {
            e.preventDefault();
            e.stopPropagation();
            if (suppressClick) {
                suppressClick = false;
                return;
            }
            setOpen(!popoverOpen);
        });

        document.body.appendChild(fab);
        restoreFabPosition();
        enableFabDrag();
    }

    function clampFabPosition(x, y) {
        var w = fab.offsetWidth || FAB_SIZE;
        var h = fab.offsetHeight || FAB_SIZE;
        return {
            x: Math.min(Math.max(0, x), Math.max(0, window.innerWidth - w)),
            y: Math.min(Math.max(0, y), Math.max(0, window.innerHeight - h))
        };
    }

    // display:none 时 getBoundingClientRect 得到零矩形，必须先判定已渲染
    function isRendered(el) {
        return !!(el && el.offsetWidth && el.offsetHeight);
    }

    function readFabPos() {
        if (!isRendered(fab)) return null;
        var r = fab.getBoundingClientRect();
        return { x: r.left, y: r.top };
    }

    // 位置持久化：拖拽释放与进入全屏共用
    function persistFabPosition() {
        var p = readFabPos();
        if (!p) return;
        lastNormalPos = { x: p.x, y: p.y };
        storage.set(KEY_POS, JSON.stringify({
            x: Math.round(p.x),
            y: Math.round(p.y)
        }));
    }

    // 恢复：内存快照 → 持久化记录 → 右下角默认；全程 left+top（清空 right/bottom）
    function restoreFabPosition() {
        var pos = lastNormalPos;
        if (!pos) {
            try {
                pos = JSON.parse(storage.get(KEY_POS, null));
            } catch (e) {
                pos = null;
            }
        }
        if (!pos || typeof pos.x !== 'number' || typeof pos.y !== 'number') {
            pos = {
                x: window.innerWidth - (fab.offsetWidth || FAB_SIZE) - 16,
                y: window.innerHeight - (fab.offsetHeight || FAB_SIZE) - 16
            };
        }
        var p = clampFabPosition(pos.x, pos.y);
        fab.style.left = p.x + 'px';
        fab.style.top = p.y + 'px';
        fab.style.right = 'auto';
        fab.style.bottom = 'auto';
        return p;
    }

    var suppressClick = false; // 拖拽释放后一次性抑制 click

    /* FAB 拖拽（Pointer Events 统一鼠标/触屏）：阈值区分点击与拖拽，
       setPointerCapture 锁定指针，rAF 节流；气泡开时传入已知矩形免重排 */
    function enableFabDrag() {
        var startX = 0;
        var startY = 0;
        var offX = 0;
        var offY = 0;
        var moved = false;
        var rafId = 0;
        var pendingX = 0;
        var pendingY = 0;
        var activePointerId = null;

        fab.addEventListener('pointerdown', function (e) {
            if (e.button !== 0) return;
            e.preventDefault();
            suppressClick = false;
            var rect = fab.getBoundingClientRect();
            startX = e.clientX;
            startY = e.clientY;
            offX = e.clientX - rect.left;
            offY = e.clientY - rect.top;
            moved = false;
            activePointerId = e.pointerId;
            try { fab.setPointerCapture(e.pointerId); } catch (err) {}
            fab.addEventListener('pointermove', onMove);
            fab.addEventListener('pointerup', onUp);
            fab.addEventListener('pointercancel', onUp);
        });

        function onMove(e) {
            if (!moved &&
                Math.hypot(e.clientX - startX, e.clientY - startY) > DRAG_THRESHOLD) {
                moved = true;
                fab.classList.add('loc-grabbing');
            }
            if (!moved) return;

            pendingX = e.clientX - offX;
            pendingY = e.clientY - offY;
            if (!rafId) rafId = requestAnimationFrame(applyFrame);
        }

        function applyFrame() {
            rafId = 0;
            var p = clampFabPosition(pendingX, pendingY);
            fab.style.left = p.x + 'px';
            fab.style.top = p.y + 'px';
            if (popoverOpen) {
                // 传入已知矩形，避免“先写后读”的强制重排
                var fw = fab.offsetWidth || FAB_SIZE;
                var fh = fab.offsetHeight || FAB_SIZE;
                positionPopover({
                    left: p.x,
                    top: p.y,
                    right: p.x + fw,
                    bottom: p.y + fh
                });
            }
        }

        function onUp() {
            fab.removeEventListener('pointermove', onMove);
            fab.removeEventListener('pointerup', onUp);
            fab.removeEventListener('pointercancel', onUp);
            if (activePointerId !== null) {
                try { fab.releasePointerCapture(activePointerId); } catch (e) {}
                activePointerId = null;
            }

            if (rafId) {
                cancelAnimationFrame(rafId);
                rafId = 0;
                applyFrame();
            }

            if (moved) {
                fab.classList.remove('loc-grabbing');
                persistFabPosition();
                suppressClick = true; // 紧随其后的 click 跳过，避免拖拽误切换
            }
        }
    }

    // 显隐状态唯一入口
    function setOpen(v) {
        popoverOpen = !!v;
        storage.set(KEY_OPEN, popoverOpen ? 1 : 0);
        syncPopover();
    }

    function isFullscreenNow() {
        return !!(document.fullscreenElement || document.webkitFullscreenElement);
    }

    /* 视频“网页全屏”检测（如 B站）：网页全屏不触发 Fullscreen API，
       站点仅给播放器容器加特征类并以 fixed 铺满视口，故需单独检测。
       特征类快速命中；否则在可见 video 的祖先中找 fixed 且覆盖视口 ≥90% 的容器。 */
    var WEB_FS_SELECTORS = [
        '.bilibili-player-web-fullscreen',
        '#bilibili-player.web-fullscreen',
        '.bwp-player-web-fullscreen',
        '.web-fullscreen',
        '.web-full-screen',
        '.is-webfullscreen',
        '.player-webfullscreen'
    ];
    var WEB_FS_COVER = 0.9;
    var WEB_FS_MAX_DEPTH = 12;

    function detectWebFullscreen() {
        try {
            var matched = null;
            try { matched = document.querySelector(WEB_FS_SELECTORS.join(',')); } catch (e) {}
            if (matched) return true;

            var videos = document.getElementsByTagName('video');
            if (!videos.length) return false;
            var vw = window.innerWidth;
            var vh = window.innerHeight;
            for (var vi = 0; vi < videos.length; vi++) {
                var video = videos[vi];
                if (!video.offsetWidth || !video.offsetHeight) continue;
                var node = video;
                for (var d = 0;
                    d < WEB_FS_MAX_DEPTH && node && node.nodeType === 1;
                    d++) {
                    var st = window.getComputedStyle(node);
                    if (st && st.position === 'fixed') {
                        var rect = node.getBoundingClientRect();
                        if (rect.width >= vw * WEB_FS_COVER &&
                            rect.height >= vh * WEB_FS_COVER) return true;
                    }
                    if (node.tagName === 'BODY') break;
                    node = node.parentElement;
                }
            }
        } catch (e) {
            return false;
        }
        return false;
    }

    /* 检测调度：observer 收集变更节点，rAF 中先预过滤（播放器相关命名，
       或自身为 fixed 的节点），通过后才执行完整检测——规避弹幕运行时
       高频 class 变更带来的无谓开销；resize 触发时直接完整检测。 */
    var webFsScheduled = false;
    var webFsCandidates = [];
    var PLAYER_LIKE_RE = /player|fullscreen|video|bwp-/i;

    function isPlayerRelated(node) {
        var depth = 0;
        while (node && node.nodeType === 1 && node !== document.body && depth < 8) {
            var sig = (node.id || '') + ' ' +
                (typeof node.className === 'string' ? node.className : '');
            if (PLAYER_LIKE_RE.test(sig)) return true;
            node = node.parentElement;
            depth++;
        }
        return false;
    }

    function scheduleWebFsCheck(nodes) {
        if (nodes) {
            for (var i = 0; i < nodes.length && webFsCandidates.length < 16; i++) {
                var n = nodes[i];
                if (n.nodeType === 1 && n.closest &&
                    !n.closest('#' + PANEL_ID + ',#' + FAB_ID)) {
                    webFsCandidates.push(n);
                }
            }
        }
        if (!webFsScheduled) {
            webFsScheduled = true;
            requestAnimationFrame(runWebFsCheck);
        }
    }

    function runWebFsCheck() {
        webFsScheduled = false;
        var candidates = webFsCandidates;
        webFsCandidates = [];

        var relevant = false;
        for (var i = 0; i < candidates.length; i++) {
            if (isPlayerRelated(candidates[i])) { relevant = true; break; }
        }
        if (!relevant) {
            for (var j = 0; j < candidates.length; j++) {
                try {
                    if (window.getComputedStyle(candidates[j]).position === 'fixed') {
                        relevant = true;
                        break;
                    }
                } catch (e) {}
            }
        }
        // observer 触发但无相关节点：跳过本次；resize 触发(candidates 为空)：完整检测
        if (candidates.length && !relevant) return;

        var v = detectWebFullscreen();
        if (v !== webFullscreen) {
            webFullscreen = v;
            syncPopover();
        }
    }

    function enableWebFullscreenAware() {
        var observer = new MutationObserver(function (mutations) {
            var nodes = [];
            for (var i = 0; i < mutations.length; i++) nodes.push(mutations[i].target);
            scheduleWebFsCheck(nodes);
        });
        observer.observe(document.documentElement, {
            attributes: true,
            attributeFilter: ['class', 'style'],
            subtree: true
        });
        scheduleWebFsCheck(null); // 初始检测
    }

    // 唯一的视口变化处理：FAB 裁剪入视口 + 网页全屏检测（仅绑定一个 resize 监听）
    function onViewportResize() {
        if (isRendered(fab)) {
            var r = fab.getBoundingClientRect();
            var p = clampFabPosition(r.left, r.top);
            fab.style.left = p.x + 'px';
            fab.style.top = p.y + 'px';
            if (popoverOpen) syncPopover();
        }
        scheduleWebFsCheck(null);
    }

    /* 气泡定位：以 FAB 为锚点按视口剩余空间选方位（上→左→下→右），
       放得下即用，否则选空间最大方向；全程 left+top，隐藏态也可测量 */
    function positionPopover(fabRect) {
        var r = fabRect || null; // 优先用调用方已知矩形（拖拽帧，避免重排）
        if (!r) {
            if (!isRendered(fab)) return false;
            r = fab.getBoundingClientRect();
        }
        var vw = window.innerWidth;
        var vh = window.innerHeight;
        var pw = panel.offsetWidth || PANEL_W;
        var ph = panel.offsetHeight || 120;

        var space = {
            above: r.top,
            left: r.left,
            below: vh - r.bottom,
            right: vw - r.right
        };
        var need = {
            above: ph + GAP,
            below: ph + GAP,
            left: pw + GAP,
            right: pw + GAP
        };

        var order = ['above', 'left', 'below', 'right'];
        var dir = '';
        for (var i = 0; i < order.length; i++) {
            if (space[order[i]] >= need[order[i]]) {
                dir = order[i];
                break;
            }
        }
        if (!dir) {
            // 都放不下：选剩余空间最大的方向
            var best = order[0];
            for (var j = 1; j < order.length; j++) {
                if (space[order[j]] > space[best]) best = order[j];
            }
            dir = best;
        }

        // 分区重排不改变面板总尺寸，已测得的 ph 仍有效
        arrangeSections(dir === 'below');

        var x;
        var y;
        if (dir === 'above') {
            x = r.right - pw;
            y = r.top - GAP - ph;
        } else if (dir === 'below') {
            x = r.right - pw;
            y = r.bottom + GAP;
        } else if (dir === 'left') {
            x = r.left - GAP - pw;
            y = r.bottom - ph;
        } else {
            x = r.right + GAP;
            y = r.bottom - ph;
        }

        x = Math.min(Math.max(0, x), Math.max(0, vw - pw));
        y = Math.min(Math.max(0, y), Math.max(0, vh - ph));

        panel.style.left = x + 'px';
        panel.style.top = y + 'px';

        panel.style.transformOrigin = {
            above: 'bottom right',
            below: 'top right',
            left: 'bottom right',
            right: 'bottom left'
        }[dir];
        return true;
    }

    /* 同步：可见性 = popoverOpen 且非浏览器全屏且非网页全屏。
       进入浏览器全屏时先保存位置，退出时先恢复再定位，防止零矩形把按钮写到左上角 */
    function syncPopover() {
        if (!panel || !fab) return;

        var isFs = isFullscreenNow();
        var hidden = isFs || webFullscreen;

        var justEntered = isFs && !wasFullscreen;
        var justExited = !isFs && wasFullscreen;
        wasFullscreen = isFs;

        if (justEntered) {
            // 进入时先保存位置（此刻仍可测量）
            persistFabPosition();
        }

        // 先切隐藏类再测量，杜绝零矩形
        panel.classList.toggle('loc-fs-hidden', hidden);
        fab.classList.toggle('loc-fs-hidden', hidden);

        var shouldShow = !hidden && popoverOpen;

        if (justExited) {
            restoreFabPosition();
        }

        if (shouldShow) {
            positionPopover(); // 展开前先定位，避免在旧位置闪现
        }

        panel.classList.toggle('loc-open', shouldShow);
        fab.classList.toggle('loc-on', popoverOpen);

        fab.setAttribute('aria-expanded', shouldShow ? 'true' : 'false');
        fab.title = popoverOpen
            ? '点击隐藏链接控制面板'
            : '点击显示链接控制面板';
    }

    // 全屏感知（含 webkit 前缀，兼容旧内核/Safari）
    function enableFullscreenAware() {
        document.addEventListener('fullscreenchange', syncPopover);
        document.addEventListener('webkitfullscreenchange', syncPopover);
    }

    function enableViewportAware() {
        window.addEventListener('resize', onViewportResize);
    }

    /* Cloudflare 整页质询（5 秒盾 / 新版 Turnstile 托管验证）检测。
       仅用质询页强特征；页面内嵌 Turnstile 登录组件不算整页质询，避免误判 */
    function isCloudflareChallenge() {
        try {
            var d = document;
            // 旧版质询 DOM 标记
            if (d.getElementById('challenge-form') ||
                d.getElementById('cf-please-wait') ||
                d.getElementById('cf-challenge-running')) return true;

            var wrap = d.getElementById('cf-wrapper');
            if (wrap && wrap.querySelector('#cf-content,.cf-turnstile,#turnstile-wrapper')) return true;

            // 整页质询编排脚本（chl_page 为整页质询独有，页面内嵌 Turnstile 不会加载）
            var scripts = d.getElementsByTagName('script');
            for (var i = 0; i < scripts.length; i++) {
                var src = scripts[i].src || '';
                if (src.indexOf('/cdn-cgi/challenge-platform/') !== -1 &&
                    src.indexOf('orchestrate/chl_page') !== -1) return true;
            }
        } catch (e) {}
        return false;
    }

    function boot() {
        modeSyncActive = enableModeSync();
        document.addEventListener('click', handleLinkClick, true);

        if (window.top === window.self &&
            !document.getElementById(PANEL_ID) && document.body) {
            injectStyles();
            buildPanel();
            buildFab();
            applyFabSize(savedFabSize, false);
            enableFullscreenAware();
            enableViewportAware();
            enableWebFullscreenAware();
            syncPopover();
        }
    }

    /* 质询期间不构建 UI、不拦截点击：避免高 z-index 悬浮按钮遮挡 Turnstile，
       也避免全局 MutationObserver 增加验证计时开销。质询通常以整页跳转结束
       （新文档会重新 init）；此处轮询兜底原地替换 DOM 的场景 */
    function watchChallengeThenBoot() {
        var tries = 0;
        var timer = setInterval(function () {
            tries++;
            if (tries > 120 || !isCloudflareChallenge()) {
                clearInterval(timer);
                if (document.body) boot();
            }
        }, 500);
    }

    /* 初始化：UI 与拦截解耦——所有框架拦截链接，仅顶层窗口构建 UI；
       Cloudflare 质询页与 Turnstile 验证 iframe 延迟/完全跳过介入 */
    function init() {
        try {
            // Turnstile 验证运行在 challenges.cloudflare.com 跨域 iframe 内，不注入任何监听
            if (window.top !== window.self &&
                location.hostname === 'challenges.cloudflare.com') return;

            if (window.top === window.self &&
                !document.getElementById(PANEL_ID) && document.body &&
                isCloudflareChallenge()) {
                watchChallengeThenBoot();
                return;
            }
            boot();
        } catch (err) {
            try { console.warn('[链接打开方式控制器] 初始化异常:', err); } catch (x) {}
        }
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', init, { once: true });
    } else {
        init();
    }
})();
